from __future__ import annotations

from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def replace_once(path: str, old: str, new: str) -> None:
    target = ROOT / path
    text = target.read_text(encoding="utf-8")
    if old not in text:
        raise RuntimeError(f"expected patch anchor missing from {path}: {old[:120]!r}")
    target.write_text(text.replace(old, new, 1), encoding="utf-8")


# Canonical Python rules: Mana is granted once to each active monster at round start.
(ROOT / "scripts/gameplay_rules.py").write_text('''from __future__ import annotations  # Enables forward-compatible type annotations.\n\nfrom typing import Any  # Describes portable move and card dictionaries.\n\nSTARTING_MANA = 0  # Every monster enters each battle with no stored mana.\nMANA_PER_ROUND = 1  # Both active monsters gain exactly one mana at the start of every battle round.\nMANA_PER_TURN = MANA_PER_ROUND  # Backward-compatible alias for older tooling; round-start gain is canonical.\nTEAM_SIZE_LIMIT = 6  # The player can carry at most six monsters and has no reserve storage.\nENEMY_FIRST_MOVE_ROLLS = range(1, 4)  # Enemy d6 results 1-3 select move one first.\nENEMY_SECOND_MOVE_ROLLS = range(4, 7)  # Enemy d6 results 4-6 select move two first.\n\n\ndef gain_round_mana(current_mana: int) -> int:  # Applies the canonical start-of-round mana gain to one active monster.\n    return max(0, int(current_mana)) + MANA_PER_ROUND  # Keeps malformed negative values from reducing the battle resource.\n\n\ndef gain_turn_mana(current_mana: int) -> int:  # Preserves the old helper name for callers outside the canonical rules path.\n    return gain_round_mana(current_mana)  # Mana is no longer granted separately inside each monster action.\n\n\ndef can_afford_move(current_mana: int, move: dict[str, Any]) -> bool:  # Checks whether a monster can legally use one move now.\n    return max(0, int(current_mana)) >= max(0, int(move.get("mana_cost", 0)))  # Compares accumulated mana with the printed move cost.\n\n\ndef spend_move_mana(current_mana: int, move: dict[str, Any]) -> int:  # Pays for a move after affordability has been established.\n    if not can_afford_move(current_mana, move):  # Rejects impossible attacks instead of allowing negative mana.\n        raise ValueError("monster does not have enough mana for that move")  # Gives callers an explicit illegal-move failure.\n    return int(current_mana) - int(move.get("mana_cost", 0))  # Removes exactly the printed mana cost from the current pool.\n\n\ndef enemy_move_index(roll: int, current_mana: int, moves: list[dict[str, Any]]) -> int | None:  # Resolves the enemy d6 choice against available mana.\n    if roll not in range(1, 7):  # Requires a genuine d6 result.\n        raise ValueError("enemy move roll must be between 1 and 6")  # Prevents accidental non-d6 values from silently choosing an attack.\n    if len(moves) != 2:  # Requires the canonical two-move monster format.\n        raise ValueError("enemy monster must have exactly two moves")  # Keeps move-selection behavior deterministic.\n    preferred = 0 if roll in ENEMY_FIRST_MOVE_ROLLS else 1  # Maps 1-3 to move one and 4-6 to move two.\n    alternate = 1 - preferred  # Identifies the other move for the affordability fallback.\n    if can_afford_move(current_mana, moves[preferred]):  # Uses the rolled move whenever the monster can pay for it.\n        return preferred  # Returns the selected zero-based move index.\n    if can_afford_move(current_mana, moves[alternate]):  # Falls back when only the other move is currently affordable.\n        return alternate  # Uses the legal attack instead of wasting a turn after a high-cost roll.\n    return None  # A monster with no affordable move skips its action and keeps accumulated mana.\n\n\ndef recruitment_requires_discard(current_team_size: int) -> bool:  # Checks whether accepting a recruited monster forces a discard choice.\n    return max(0, int(current_team_size)) >= TEAM_SIZE_LIMIT  # A full six-monster team must discard either the recruit or one carried monster.\n\n\ndef move_two_is_stronger(card: dict[str, Any]) -> bool:  # Checks the canonical ordering of every monster's two attacks.\n    moves = list(card.get("moves", []))  # Reads the complete move pair from portable card data.\n    if len(moves) != 2:  # Rejects incomplete or expanded move sets.\n        return False  # Keeps validation strict around the two-move game design.\n    first, second = moves  # Names the weaker and stronger attack slots.\n    return int(second.get("mana_cost", 0)) > int(first.get("mana_cost", 0)) and int(second.get("damage", 0)) > int(first.get("damage", 0))  # Requires move two to cost more mana and deal more damage.\n''', encoding="utf-8")

# Deterministic digital engine: action functions spend existing Mana only.
(ROOT / "digital_game/engine.js").write_text('''export const TEAM_SIZE_LIMIT = 6;\nexport const FINAL_LOCATION_ID = "loc_100";\nexport const FINAL_BOSS_SPECIES_ID = "0400";\n\nexport function rollD6(random = Math.random) {\n  return Math.floor(random() * 6) + 1;\n}\n\nexport function isValidD6Roll(roll) {\n  return Number.isInteger(Number(roll)) && Number(roll) >= 1 && Number(roll) <= 6;\n}\n\nexport function buildAdjacency(mapData) {\n  const adjacency = new Map((mapData.locations || []).map((location) => [String(location.id), []]));\n  for (const link of mapData.links || []) {\n    const source = String(link.source);\n    const target = String(link.target);\n    if (!adjacency.has(source) || !adjacency.has(target)) continue;\n    adjacency.get(source).push(target);\n    adjacency.get(target).push(source);\n  }\n  return adjacency;\n}\n\nexport function getStartingLocations(mapData, adjacency = buildAdjacency(mapData)) {\n  return (mapData.locations || []).filter((location) => {\n    const id = String(location.id);\n    return id !== FINAL_LOCATION_ID && (adjacency.get(id) || []).length === 1;\n  });\n}\n\nexport function buildCardIndex(cardData) {\n  return new Map((cardData.cards || []).map((card) => [String(card.species_id), card]));\n}\n\nexport function encounterForRoll(location, roll) {\n  if (!isValidD6Roll(roll)) return null;\n  const encounters = Array.isArray(location?.encounters) ? location.encounters : [];\n  return encounters.find((entry) => Number(entry.roll) === Number(roll)) || encounters[Number(roll) - 1] || null;\n}\n\nexport function createMonsterInstance(card, instanceId) {\n  return {\n    instance_id: String(instanceId),\n    species_id: String(card.species_id),\n    species_name: String(card.species_name),\n    type: String(card.type),\n    max_health: Number(card.health),\n    current_health: Number(card.health),\n    speed: Number(card.speed),\n    moves: (card.moves || []).map((move) => ({\n      name: String(move.name),\n      mana_cost: Number(move.mana_cost),\n      damage: Number(move.damage),\n    })),\n    battle_mana: 0,\n  };\n}\n\nexport function resetBattleMana(team) {\n  for (const monster of team) monster.battle_mana = 0;\n}\n\nexport function grantRoundMana(player, enemy) {\n  for (const monster of [player, enemy]) {\n    if (!monster || Number(monster.current_health) <= 0) continue;\n    monster.battle_mana = Math.max(0, Number(monster.battle_mana || 0)) + 1;\n  }\n}\n\nexport function canAffordMove(monster, moveIndex) {\n  const move = monster?.moves?.[moveIndex];\n  if (!move) return false;\n  return Number(monster.battle_mana || 0) >= Number(move.mana_cost || 0);\n}\n\nexport function hasAffordableMove(monster) {\n  return Array.isArray(monster?.moves) && monster.moves.some((_, index) => canAffordMove(monster, index));\n}\n\nexport function chooseEnemyMove(enemy, roll) {\n  if (!isValidD6Roll(roll)) throw new Error("enemy move roll must be between 1 and 6");\n  const preferred = Number(roll) <= 3 ? 0 : 1;\n  const alternate = 1 - preferred;\n  if (canAffordMove(enemy, preferred)) return preferred;\n  if (canAffordMove(enemy, alternate)) return alternate;\n  return null;\n}\n\nexport function compareSpeed(player, enemy) {\n  if (Number(player.speed) > Number(enemy.speed)) return "player";\n  if (Number(enemy.speed) > Number(player.speed)) return "enemy";\n  return "tie";\n}\n\nexport function resolveSpeedTie(playerRoll, enemyRoll) {\n  if (!isValidD6Roll(playerRoll) || !isValidD6Roll(enemyRoll)) throw new Error("speed tie rolls must each be between 1 and 6");\n  if (Number(playerRoll) > Number(enemyRoll)) return "player";\n  if (Number(enemyRoll) > Number(playerRoll)) return "enemy";\n  return "tie";\n}\n\nexport function applyDamage(monster, damage) {\n  monster.current_health = Math.max(0, Number(monster.current_health) - Math.max(0, Number(damage)));\n  return monster.current_health === 0;\n}\n\nexport function healMonster(monster) {\n  const wasDamaged = monster.current_health < monster.max_health;\n  monster.current_health = monster.max_health;\n  return wasDamaged;\n}\n\nexport function enemyTurn(enemy, target, roll) {\n  if (!isValidD6Roll(roll)) throw new Error("enemy move roll must be between 1 and 6");\n  const moveIndex = chooseEnemyMove(enemy, roll);\n  if (moveIndex === null) return { roll: Number(roll), moveIndex: null, damage: 0, killed: false };\n  const move = enemy.moves[moveIndex];\n  enemy.battle_mana -= move.mana_cost;\n  const killed = applyDamage(target, move.damage);\n  return { roll: Number(roll), moveIndex, damage: move.damage, killed };\n}\n\nexport function playerTurn(player, enemy, moveIndex) {\n  const move = player?.moves?.[moveIndex];\n  if (!move || !canAffordMove(player, moveIndex)) {\n    return { moveIndex: null, damage: 0, killed: false };\n  }\n  player.battle_mana -= move.mana_cost;\n  const killed = applyDamage(enemy, move.damage);\n  if (killed) player.battle_mana = 0;\n  return { moveIndex, damage: move.damage, killed };\n}\n\nexport function recruitmentSucceeded(roll) {\n  if (!isValidD6Roll(roll)) throw new Error("recruitment roll must be between 1 and 6");\n  return { roll: Number(roll), success: Number(roll) >= 5 };\n}\n\nexport function isHealingLocation(locationId, healingLocationIds) {\n  return healingLocationIds instanceof Set && healingLocationIds.has(String(locationId));\n}\n\nexport function serializeState(state) {\n  return JSON.stringify(state);\n}\n\nexport function parseState(serialized) {\n  const state = JSON.parse(serialized);\n  if (!state || typeof state !== "object" || !Array.isArray(state.team)) throw new Error("invalid save data");\n  if (state.team.length > TEAM_SIZE_LIMIT) throw new Error("save exceeds six-monster team limit");\n  return state;\n}\n''', encoding="utf-8")

